import sys

def is_prime(num):
    if num < 2:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def main():
    n = int(sys.stdin.read().strip())
    colors = [0] * n
    color_count = 0

    for i in range(2, n + 2):
        prime_divisors = [j for j in range(2, i) if i % j == 0 and is_prime(j)]
        used_colors = set(colors[j - 2] for j in prime_divisors if j - 2 < n)
        for color in range(1, color_count + 2):
            if color not in used_colors:
                colors[i - 2] = color
                break
        else:
            color_count += 1
            colors[i - 2] = color_count

    print(color_count)
    print(' '.join(map(str, colors)))

main()
